// FUSE — combine elements. Recipes were pre-generated by a local LLM (recipes.json); when BALLPARK runs locally,
// unknown combos are invented live by Ollama through serve.js (../../api/fuse) and cached on this device.
const BP = window.Ballpark;
const store = BP.store('fuse');
const $ = id => document.getElementById(id);
const board = $('board'), list = $('list');
const LIVE = ['localhost', '127.0.0.1'].includes(location.hostname);

async function loadRecipes() {
  for (let i = 0; i < 4; i++) {
    try { return await fetch('recipes.json', { cache: 'no-cache' }).then(r => r.json()); }
    catch { await new Promise(r => setTimeout(r, 400)); }        // retry (e.g. file mid-write)
  }
  return { elements: [], recipes: [] };
}
const data = await loadRecipes();
const EMOJI = new Map(data.elements.map(e => [e.n, e.e]));
const RECIPES = new Map();
const key = (a, b) => [a.toLowerCase(), b.toLowerCase()].sort().join('|');
for (const [a, b, r] of data.recipes) RECIPES.set(key(data.elements[a].n, data.elements[b].n), data.elements[r].n);
const live = store.get('live', {});                         // combos invented on this device
for (const [k, v] of Object.entries(live)) { if (v) { RECIPES.set(k, v.n); EMOJI.set(v.n, v.e); } }

const BASICS = [['Water', '💧'], ['Fire', '🔥'], ['Wind', '🌬️'], ['Earth', '🌍']];
let found = store.get('found', null) || BASICS.map(([n, e]) => ({ n, e, t: 0 }));
let sortMode = store.get('sort', 'newest'), fresh = new Set(), muted = store.get('muted', false);
const emojiOf = n => EMOJI.get(n) || found.find(f => f.n === n)?.e || '✨';

// ---------- sidebar ----------
function renderList() {
  const q = $('search').value.trim().toLowerCase();
  const items = found.filter(f => !q || f.n.toLowerCase().includes(q));
  items.sort(sortMode === 'az' ? (a, b) => a.n.localeCompare(b.n) : (a, b) => b.t - a.t);
  list.innerHTML = items.map(f => `<div class="item ${fresh.has(f.n) ? 'new' : ''}" data-n="${f.n.replace(/"/g, '&quot;')}"><span class="e">${f.e}</span>${f.n}</div>`).join('');
  $('count').textContent = `${found.length} discovered`;
  $('sort').textContent = 'Sort: ' + (sortMode === 'az' ? 'A–Z' : 'newest');
}
$('search').addEventListener('input', renderList);
$('sort').onclick = () => { sortMode = sortMode === 'az' ? 'newest' : 'az'; store.set('sort', sortMode); renderList(); };

// ---------- board items + dragging ----------
function spawn(n, x, y, cls = 'pop', clamp = true) {
  const el = document.createElement('div');
  el.className = 'item ' + cls;
  el.dataset.n = n;
  el.innerHTML = `<span class="e">${emojiOf(n)}</span>${n}`;
  board.append(el);
  const r = board.getBoundingClientRect();
  const lx = x - el.offsetWidth / 2, ly = y - el.offsetHeight / 2;
  // while dragging out of the list the item must sit exactly under the pointer, so no clamping then
  el.style.left = (clamp ? Math.max(4, Math.min(r.width - el.offsetWidth - 4, lx)) : lx) + 'px';
  el.style.top = (clamp ? Math.max(60, Math.min(r.height - el.offsetHeight - 4, ly)) : ly) + 'px';
  $('first').hidden = true;
  return el;
}
let drag = null, picked = null;
function startDrag(el, e) {
  const r = el.getBoundingClientRect();
  drag = { el, dx: e.clientX - r.left, dy: e.clientY - r.top, sx: e.clientX, sy: e.clientY, moved: false };
  el.classList.add('drag');
  el.setPointerCapture?.(e.pointerId);
}
list.addEventListener('pointerdown', e => {
  const src = e.target.closest('.item'); if (!src) return;
  e.preventDefault();
  const b = board.getBoundingClientRect();
  const inBoard = window.innerWidth > 720;
  const el = spawn(src.dataset.n, inBoard ? e.clientX - b.left : b.width / 2 + (Math.random() - .5) * 120, inBoard ? e.clientY - b.top : b.height / 2 + (Math.random() - .5) * 80, '', !inBoard);
  if (inBoard) startDrag(el, e); else { el.classList.add('pop'); tapPick(el); }
  sfx(520);
});
board.addEventListener('pointerdown', e => {
  const el = e.target.closest('.item'); if (!el || el.parentElement !== board) return;
  e.preventDefault(); startDrag(el, e);
});
addEventListener('pointermove', e => {
  if (!drag) return;
  const b = board.getBoundingClientRect();
  drag.el.style.left = (e.clientX - b.left - drag.dx) + 'px';
  drag.el.style.top = (e.clientY - b.top - drag.dy) + 'px';
  if (Math.hypot(e.clientX - drag.sx, e.clientY - drag.sy) > 4) drag.moved = true;
  board.querySelectorAll('.item.target').forEach(t => t.classList.remove('target'));
  overlapTarget(drag.el)?.classList.add('target');
});
addEventListener('pointerup', e => {
  if (!drag) return;
  const { el, moved } = drag; drag = null;
  el.classList.remove('drag');
  board.querySelectorAll('.item.target').forEach(t => t.classList.remove('target'));
  const b = board.getBoundingClientRect();
  if (e.clientX > b.right || e.clientY > b.bottom) { el.remove(); return; }   // dropped back on the list
  const t = overlapTarget(el);
  if (t) combine(el, t);
  else if (!moved) tapPick(el);
});
function overlapTarget(el) {
  const a = el.getBoundingClientRect(), cx = a.left + a.width / 2, cy = a.top + a.height / 2;
  let best = null, bd = 1e9;
  for (const o of board.querySelectorAll('.item')) {
    if (o === el) continue;
    const r = o.getBoundingClientRect();
    if (cx > r.left - 10 && cx < r.right + 10 && cy > r.top - 10 && cy < r.bottom + 10) {
      const d = Math.hypot(cx - (r.left + r.width / 2), cy - (r.top + r.height / 2)); if (d < bd) { bd = d; best = o; }
    }
  }
  return best;
}
function tapPick(el) {                                       // tap-tap combining for touch screens
  if (picked && picked !== el && picked.isConnected) { const p = picked; picked = null; p.classList.remove('picked'); return combine(el, p); }
  picked?.classList.remove('picked');
  picked = el; el.classList.add('picked');
}

// ---------- combining ----------
let busy = false;
async function combine(a, b) {
  if (busy) return;
  const A = a.dataset.n, B = b.dataset.n, k = key(A, B);
  let result = RECIPES.get(k);
  if (!result && LIVE && !(k in live)) {
    busy = true; a.style.opacity = b.style.opacity = '.55';
    try {
      const r = await fetch('../../api/fuse', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ a: A, b: B }) });
      if (r.ok) { const j = await r.json(); if (j.n) { result = j.n; EMOJI.set(j.n, j.e); live[k] = { n: j.n, e: j.e }; } else live[k] = null; store.set('live', live); RECIPES.set(k, result); }
    } catch { /* offline: fall through */ }
    a.style.opacity = b.style.opacity = ''; busy = false;
  }
  if (!result) {
    a.classList.remove('nope'); void a.offsetWidth; a.classList.add('nope'); sfx(160, 'square');
    if (!LIVE && !store.get('toldLive', false)) { store.set('toldLive', true); toast('Nothing happened. (Run BALLPARK locally with Ollama to invent new combos live.)'); }
    return;
  }
  const ra = a.getBoundingClientRect(), rb = b.getBoundingClientRect(), bb = board.getBoundingClientRect();
  const x = (ra.left + ra.right + rb.left + rb.right) / 4 - bb.left, y = (ra.top + ra.bottom + rb.top + rb.bottom) / 4 - bb.top;
  a.remove(); b.remove();
  spawn(result, x, y);
  if (!found.some(f => f.n === result)) {
    found.push({ n: result, e: emojiOf(result), t: Date.now() });
    fresh.add(result); store.set('found', found);
    toast(`New discovery: ${emojiOf(result)} ${result}`);
    sfx(880); setTimeout(() => sfx(1320), 90);
    BP.report('fuse', { score: found.length, label: `${found.length} discovered` });
    renderList();
  } else sfx(660);
}

function toast(t) { const el = $('toast'); el.textContent = t; el.hidden = false; clearTimeout(toast.h); toast.h = setTimeout(() => { el.hidden = true; }, 2200); }
let ac = null;
function sfx(f, type = 'triangle') {
  if (muted) return;
  try { ac = ac || new AudioContext(); const o = ac.createOscillator(), g = ac.createGain(), t = ac.currentTime;
    o.type = type; o.frequency.value = f; g.gain.setValueAtTime(0.06, t); g.gain.exponentialRampToValueAtTime(0.0001, t + 0.12);
    o.connect(g).connect(ac.destination); o.start(t); o.stop(t + 0.13); } catch { /* no audio */ }
}
$('mute').textContent = muted ? '🔇' : '🔊';
$('mute').onclick = () => { muted = !muted; store.set('muted', muted); $('mute').textContent = muted ? '🔇' : '🔊'; };
$('clear').onclick = () => { board.querySelectorAll('.item').forEach(i => i.remove()); picked = null; };
$('share').onclick = () => navigator.clipboard?.writeText(`Fuse: I've discovered ${found.length} things ✨ — latest: ${found.slice().sort((a, b) => b.t - a.t).slice(0, 5).map(f => f.e + ' ' + f.n).join(', ')}\nBALLPARK`).then(() => toast('Copied!'));
renderList();
